 "content": "def transform(grid):
    """Fill cells between any two aligned marker cells with color 3."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = 5 if any(5 in row for row in grid) else 9 if any(9 in row for row in grid) else 6
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
